/// <summary>
/// AVA/WEN/2025/05/21      AVA_013218_ProdSetupRelease
/// </summary>
[DataContractAttribute]
class AVAProdSetupReleaseRecordContract implements SysOperationValidatable
{
    AVACheckCode    checkCode;
    ProdId          prodId;

}

Method.Source:
[DataMemberAttribute]
public AVACheckCode parmCheckCode(avaCheckCode _CheckCode = checkcode)
{
    checkCode = _CheckCode;
    return checkCode;
}

public ProdId parmProdId(ProdId _prodId = prodid)
{
    prodId = _prodId;
    return prodId;
}

public boolean validate()
{
    boolean isValid = true;

    if (!checkCode)
    {
        isValid = checkFailed("@RET3437");
    }
    else if (!AVAProdSetupRelease::exist(checkCode))
    {
        isValid = checkFailed("@NDX:NXACodeNotFound");
    }

    return isValid;
}
